 /* pkgFBD, ASK 296 (Wall 6433 item 3; widened to MEETS or STANDS, Eric 17:40 CST 11-14): a send-back or gate change that sets MEETS or STANDS on a line that rests on DG-8 FORBIDDEN content is NOT APPLIED; the old line stays. Triggers are W3 6439 F1 to F3 with the 6444 widening (father by law; gennao begetter). MEANS: "..." is the press, not the grade, and is not read. */ function fbdHit2024(t){try{const s=String(t==null?'':t).replace(/\\+/g,'').replace(/[‘’]/g,"'").replace(/[“”]/g,'"').replace(/[*_`]+/g,'').replace(/\bMEANS\s*:\s*"[^"]*"\s*(?:--)?/gi,' ');const F=[['F1 (no human father)',/\b(?:no\s+human\s+(?:biological\s+)?(?:father|begetter)|without\s+a\s+(?:human|earthly|natural)\s+father|no\s+father\s+but\s+God|father\s+by\s+law|legal\s+father|by\s+law,?\s+not\s+by\s+begetting|by\s+supposition\s+and\s+by\s+law)\b/i],['F2 (the Holy Ghost as begetter of the flesh)',/\b(?:begetter\s+of\s+the\s+flesh|Holy\s+(?:Ghost|Spirit)\s+(?:conceived|begat|begot|fathered|supplied\s+the\s+seed)|Holy\s+(?:Ghost|Spirit)\s+(?:as|is)\s+(?:the\s+)?begetter|names\s+the\s+Holy\s+(?:Ghost|Spirit)\s+as\s+(?:the\s+)?begetter|stands\s+in\s+the\s+begetter'?s\s+place|ek\s+pneumatos[^.]{0,60}begetter|genn\S*[^.]{0,80}\bnames?\s+the\s+begetter)/i],['F3 (flesh through Mary alone)',/\b(?:David'?s\s+seed\s+is\s+in\s+Mary|Mary'?s\s+(?:own\s+)?descent\s+supplies\s+the\s+flesh|route\s+through\s+(?:a|the)\s+mother'?s\s+bearing|seed[^.]{0,60}\breach(?:es)?\s+the\s+child\s+through\s+(?:a|the|her)\s+(?:mother|Mary|woman)|Mary\s+is\s+of\s+the\s+house\s+of\s+David|flesh[^.]{0,40}\bthrough\s+Mary\s+alone)/i]];
 for(const [n,re] of F){const m=s.match(re);if(!m)continue;const pre=s.slice(Math.max(0,m.index-40),m.index);if(/\b(?:not|never|denies|refutes|rejects|against)\b[^.;]*$/i.test(pre))continue;return {f:n,q:m[0]};}return null;}catch(e){return null;}}
 function fbdRefuse2024(to){try{const s=String(to==null?'':to).replace(/\\+/g,'').replace(/[*_`]+/g,'');if(!/(?:--\s*(?:MEETS|STANDS)\b|:\s*STANDS\b)/.test(s))return null;const h=fbdHit2024(s);if(!h)return null;return 'the change sets '+(/--\s*MEETS\b/.test(s)?'MEETS':'STANDS')+' on DG-8 FORBIDDEN content, '+h.f+': "'+h.q.slice(0,160)+'". A send-back or gate change cannot turn a line into MEETS or STANDS on that ground (pkgFBD, ASK 296; DG-8). CHANGE TO the line graded without resting on it, or KEEP, and the change stays unapplied.';}catch(e){return null;}}
